-- Schema inicial gerado do modelo JPA e revisado para PostgreSQL.
create table agendamentos_atendimento (cobranca_id bigint not null, criado_em timestamp(6) with time zone not null, fim_em timestamp(6) with time zone not null, id bigint generated by default as identity, inicio_em timestamp(6) with time zone not null, status varchar(20) not null check ((status in ('AGENDADO','CONCLUIDO','CANCELADO'))), responsavel varchar(150) not null, titulo varchar(160) not null, observacao varchar(1000), primary key (id));
create table atendimento_anexos (criptografado boolean default false not null, cobranca_id bigint not null, enviado_em timestamp(6) with time zone not null, id bigint generated by default as identity, tamanho bigint not null, classificacao varchar(30) default 'OUTRO' not null check ((classificacao in ('COMPROVANTE','DOCUMENTO','OUTRO'))), sha256 varchar(64) not null, tipo_conteudo varchar(100) not null, enviado_por varchar(150) not null, nome_original varchar(255) not null, conteudo bytea not null, primary key (id));
create table atendimento_mensagens (atendimento_id bigint not null, enviada_em timestamp(6) with time zone not null, id bigint generated by default as identity, autor varchar(20) not null check ((autor in ('OPERADOR','CLIENTE','SISTEMA'))), mensagem varchar(4000) not null, primary key (id));
create table atendimentos (cobranca_id bigint not null, id bigint generated by default as identity, realizado_em timestamp(6) with time zone not null, canal varchar(30) not null check ((canal in ('CHAT'))), resultado varchar(30) not null check ((resultado in ('SEM_CONTATO','ATENDEU','NEGOCIACAO','PROMESSA','PAGAMENTO','VISITA','SUPERVISOR','ENCERRAMENTO'))), operador_identificador varchar(150) not null, operador_nome varchar(150) not null, proxima_acao varchar(1000) not null, observacao varchar(4000) not null, primary key (id));
create table backlog_itens (ordem integer not null, prioridade varchar(5) not null check ((prioridade in ('P0','P1','P2','P3'))), id bigint generated by default as identity, codigo varchar(30) not null, status varchar(30) not null check ((status in ('NAO_INICIADO','EM_ANDAMENTO','IMPLEMENTADO','BLOQUEADO'))), responsavel varchar(150), titulo varchar(200) not null, descricao varchar(1000) not null, criterio_aceite varchar(2000) not null, primary key (id), constraint uk_backlog_codigo unique (codigo));
create table clientes (atualizado_em timestamp(6) with time zone not null, id bigint generated by default as identity, cpf varchar(14) not null unique, rbx_codigo varchar(80), telefone varchar(80), email varchar(254), nome_completo varchar(255) not null, primary key (id));
create table cobranca_boletos (ativo boolean default true not null, valor numeric(19,2) not null, vencimento date not null, cobranca_id bigint not null, id bigint generated by default as identity, primeira_deteccao_em timestamp(6) with time zone not null, ultima_deteccao_em timestamp(6) with time zone not null, contrato_referencia varchar(120), rbx_documento varchar(120) not null, primary key (id), constraint uk_boleto_rbx unique (rbx_documento));
create table cobrancas (dias_atraso integer default 0 not null, sla_escalonamento_nivel integer default 0 not null, sla_horas integer default 24 not null, valor_total numeric(19,2) not null, atualizada_em timestamp(6) with time zone not null, cliente_id bigint not null, criada_em timestamp(6) with time zone not null, encerrada_em timestamp(6) with time zone, estado_fluxo_desde timestamp with time zone default current_timestamp not null, id bigint generated by default as identity, sla_alertado_em timestamp(6) with time zone, sla_pausa_segundos bigint default 0 not null, sla_pausado_em timestamp(6) with time zone, sla_ultima_notificacao_em timestamp(6) with time zone, ultima_movimentacao_em timestamp with time zone default current_timestamp not null, cpf_agregador varchar(14) not null, prioridade varchar(20) default 'MEDIA' not null check ((prioridade in ('BAIXA','MEDIA','ALTA','CRITICA'))), status varchar(20) not null check ((status in ('ABERTA','EM_ANDAMENTO','ENCERRADA','PAGA','CANCELADA'))), faixa_atraso varchar(30) default 'F1_RECENTE' not null check ((faixa_atraso in ('F1_RECENTE','F2_INICIAL','F3_INTERMEDIARIO','F4_AVANCADO','F5_CRITICO','F6_JURIDICO'))), referencia varchar(50) not null unique, estado_fluxo varchar(60) default 'NOVO' not null, fluxo_codigo varchar(60) default 'COBRANCA_PADRAO' not null, motivo_encerramento_codigo varchar(60), motivo_reabertura_codigo varchar(60), motivo_encerramento_nome varchar(120), motivo_reabertura_nome varchar(120), operador_identificador varchar(150) default 'RBX' not null, operador_nome varchar(150) default 'Integracao RBX' not null, responsavel_identificador varchar(150) default 'FILA_COBRANCA' not null, responsavel_nome varchar(150) default 'Fila de Cobranca' not null, contrato_referencia varchar(500) default 'NAO_INFORMADO' not null, motivo_encerramento varchar(500), observacao_encerramento varchar(1000), observacao_reabertura varchar(1000), primary key (id));
create table execucoes_retencao (itens_avaliados integer not null, itens_processados integer not null, modo_simulacao boolean not null, concluida_em timestamp(6) with time zone, id bigint generated by default as identity, iniciada_em timestamp(6) with time zone not null, status varchar(20) not null check ((status in ('INICIADA','CONCLUIDA','FALHOU'))), detalhes varchar(4000) not null, primary key (id));
create table faixas_atraso (dias_fim integer, dias_inicio integer not null, ordem integer not null, id bigint generated by default as identity, prioridade varchar(20) not null check ((prioridade in ('BAIXA','MEDIA','ALTA','CRITICA'))), codigo varchar(30) not null, nome varchar(100) not null, primary key (id), constraint uk_faixa_codigo unique (codigo), constraint uk_faixa_ordem unique (ordem));
create table falhas_sincronizacao_rbx (max_tentativas integer not null, tentativas integer not null, criada_em timestamp(6) with time zone not null, id bigint generated by default as identity, proxima_tentativa_em timestamp(6) with time zone not null, resolvida_em timestamp(6) with time zone, ultima_tentativa_em timestamp(6) with time zone, versao bigint not null, status varchar(20) not null check ((status in ('PENDENTE','PROCESSANDO','RESOLVIDA','ESGOTADA'))), origem varchar(80) not null, mensagem varchar(2000), primary key (id));
create table fechamentos_mensais (valor_recuperado numeric(19,2) not null, versao integer not null, competencia varchar(7) not null, atendimentos_registrados bigint not null, gerado_em timestamp(6) with time zone not null, id bigint generated by default as identity, promessas_criadas bigint not null, protocolos_encerrados bigint not null, status varchar(20) not null check ((status in ('GERADO','APROVADO','CANCELADO'))), gerado_por varchar(150) not null, observacao varchar(1000), primary key (id));
create table fluxo_estados (inicial boolean not null, ordem_exibicao integer not null, terminal boolean not null, fluxo_id bigint not null, id bigint generated by default as identity, codigo varchar(60) not null, nome varchar(120) not null, primary key (id), unique (fluxo_id, codigo));
create table fluxo_transicoes (automatica boolean not null, horas_sem_resposta integer, fluxo_id bigint not null, id bigint generated by default as identity, destino_codigo varchar(60) not null, origem_codigo varchar(60) not null, nome varchar(150) not null, primary key (id));
create table fluxos_cobranca (ativo boolean not null, padrao boolean not null, atualizado_em timestamp(6) with time zone not null, criado_em timestamp(6) with time zone not null, id bigint generated by default as identity, codigo varchar(60) not null unique, nome varchar(150) not null, primary key (id));
create table historico_atrasos (data_pagamento date, valor numeric(19,2) not null, vencimento date not null, dias_atraso bigint not null, id bigint generated by default as identity, primeira_deteccao_em timestamp(6) with time zone not null, ultima_deteccao_em timestamp(6) with time zone not null, cpf varchar(14) not null, situacao varchar(20) not null, boleto_referencia varchar(120) not null unique, contrato_referencia varchar(120), cliente_nome varchar(255) not null, primary key (id));
create table incidentes_seguranca (titulares_afetados integer not null, atualizado_em timestamp(6) with time zone not null, comunicado_em timestamp(6) with time zone, criado_em timestamp(6) with time zone not null, id bigint generated by default as identity, severidade varchar(20) not null check ((severidade in ('BAIXA','MEDIA','ALTA','CRITICA'))), status varchar(30) not null check ((status in ('ABERTO','EM_INVESTIGACAO','CONTIDO','COMUNICADO','ENCERRADO'))), protocolo varchar(40) not null unique, atualizado_por varchar(150) not null, criado_por varchar(150) not null, titulo varchar(200) not null, comunicacao_anpd varchar(2000), dados_afetados varchar(2000) not null, descricao varchar(4000) not null, medidas_adotadas varchar(4000), primary key (id));
create table logs_auditoria (criado_em timestamp(6) with time zone not null, id bigint generated by default as identity, cpf varchar(14), cobranca_referencia varchar(50), evento varchar(80) not null, boleto_referencia varchar(120), descricao varchar(1000) not null, cliente_nome varchar(255), usuario_identificador varchar(255), usuario_nome varchar(255), primary key (id));
create table motivos_catalogo (ativo boolean not null, exige_observacao boolean not null, ordem integer not null, id bigint generated by default as identity, tipo varchar(40) not null check ((tipo in ('MOVIMENTACAO','ENCERRAMENTO','REABERTURA','VISITA','RETIRADA','JURIDICO','CANCELAMENTO_FECHAMENTO'))), codigo varchar(60) not null, nome varchar(120) not null, descricao varchar(500), primary key (id), constraint uk_motivo_tipo_codigo unique (tipo, codigo));
create table politicas_lgpd (retencao_meses integer, aprovada_em timestamp(6) with time zone, id bigint generated by default as identity, destino_final varchar(30) not null check ((destino_final in ('ELIMINAR','ANONIMIZAR','CONSERVAR_BLOQUEADO'))), status_aprovacao varchar(30) not null check ((status_aprovacao in ('PENDENTE_APROVACAO','APROVADA','REJEITADA'))), codigo varchar(50) not null, categoria varchar(120) not null, aprovada_por varchar(150), base_legal varchar(500) not null, origem varchar(500) not null, perfis_acesso varchar(500) not null, dados_pessoais varchar(1000) not null, finalidade varchar(1000) not null, observacao_aprovacao varchar(1000), primary key (id), constraint uk_politica_lgpd_codigo unique (codigo));
create table processo_timeline (cobranca_id bigint not null, criado_em timestamp(6) with time zone not null, id bigint generated by default as identity, evento varchar(80) not null, autor_identificador varchar(150) not null, autor_nome varchar(150) not null, descricao varchar(1000) not null, primary key (id));
create table promessas_pagamento (valor numeric(19,2) not null, vencimento date not null, atualizada_em timestamp(6) with time zone not null, cobranca_id bigint not null, criada_em timestamp(6) with time zone not null, id bigint generated by default as identity, status varchar(20) not null check ((status in ('ABERTA','CUMPRIDA','QUEBRADA','CANCELADA'))), operador_identificador varchar(150) not null, operador_nome varchar(150) not null, observacao varchar(1000), primary key (id));
create table sincronizacao_rbx_config (ativo boolean not null, horario_primeira time(0) not null, horario_segunda time(0) not null, ultima_primeira date, ultima_segunda date, id bigint not null, fuso_horario varchar(60) not null, primary key (id));
create table sincronizacoes_rbx_execucoes (boletos_criados integer, cobrancas_criadas integer, documentos_recebidos integer, vencidos integer, duracao_ms bigint not null, finalizada_em timestamp(6) with time zone not null, id bigint generated by default as identity, iniciada_em timestamp(6) with time zone not null, status varchar(20) not null check ((status in ('SUCESSO','FALHA'))), origem varchar(80) not null, mensagem varchar(2000), primary key (id));
create table solicitacoes_atualizacao_cliente (cliente_id bigint not null, decidido_em timestamp(6) with time zone, id bigint generated by default as identity, solicitado_em timestamp(6) with time zone not null, status varchar(20) not null check ((status in ('PENDENTE','APROVADA','REJEITADA'))), novo_telefone varchar(80), decidido_por varchar(150), solicitado_por varchar(150) not null, novo_email varchar(254), motivo varchar(500) not null, primary key (id));
create table tarefas_cobranca (cobranca_id bigint not null, criada_em timestamp(6) with time zone not null, id bigint generated by default as identity, prazo_em timestamp(6) with time zone not null, prioridade varchar(20) not null check ((prioridade in ('BAIXA','MEDIA','ALTA','CRITICA'))), status varchar(20) not null check ((status in ('PENDENTE','EM_ANDAMENTO','CONCLUIDA','CANCELADA'))), tipo varchar(80) not null, responsavel_identificador varchar(150) not null, responsavel_nome varchar(150) not null, titulo varchar(250) not null, primary key (id));
create table usuarios (ativo boolean not null, carga_maxima integer not null, falhas_login integer default 0 not null, presente boolean not null, troca_senha_obrigatoria boolean default true not null, atualizado_em timestamp(6) with time zone not null, bloqueado_ate timestamp(6) with time zone, criado_em timestamp(6) with time zone not null, id bigint generated by default as identity, senha_alterada_em timestamp(6) with time zone, ultimo_login_em timestamp(6) with time zone, versao_token bigint default 0 not null, perfil varchar(30) not null check ((perfil in ('OPERADOR','SUPERVISOR','FINANCEIRO','CAMPO','JURIDICO','GERENTE','ADMINISTRADOR'))), identificador varchar(80) not null unique, senha_hash varchar(100) not null, nome varchar(150) not null, primary key (id));
